private boolean hasLayoutWidthOrHeightInStyle(XmlContext context, String style) {
    ResourceUrl url = ResourceUrl.parse(style);
    if (url == null || url.type != ResourceType.STYLE) return false;
    Project project = context.getMainProject();
    ResourceLibrary resourceLibrary = project.getPartialResourceLibrary();
    if (resourceLibrary == null) return false;
    StyleResourceValue styleValue = resourceLibrary.getStyle(url.name);
    while (styleValue != null) {
        if (styleValue.getItem(SdkConstants.ATTR_LAYOUT_WIDTH) != null
                || styleValue.getItem(SdkConstants.ATTR_LAYOUT_HEIGHT) != null) {
            return true;
        }
        String parent = styleValue.getParentStyle();
        if (parent == null) return false;
        url = ResourceUrl.parse(parent);
        if (url == null || url.type != ResourceType.STYLE) return false;
        styleValue = resourceLibrary.getStyle(url.name);
    }
    return false;
}
```

