import org.w3c.dom.Attr;
import org.w3c.dom.Element;

import java.util.Arrays;
import java.util.Collection;
import java.util.Map;

public class RequiredAttributeDetector extends ResourceXmlDetector {
    /** Missing layout width or height */
    public static final Issue ISSUE = Issue.create(
            "RequiredSize",
            "Missing layout_width or layout_height attributes",
            "The `layout_width` and `layout_height` attributes are required for most views. ...",
            Category.CORRECTNESS,
            9,
            Severity.FATAL,
            new Implementation(
                    RequiredAttributeDetector.class,
                    Scope.RESOURCE_FILE_SCOPE));

    private static final String GRID_LAYOUT = "GridLayout";

    private Map<Element, Boolean> mWidthNodes;
    private Map<Element, Boolean> mHeightNodes;
    private Map<Element, Attr> mStyleNodes;

    @Override
    public void beforeCheckProject(@NonNull Context context) {
        mWidthNodes = Maps.newHashMap();
        mHeightNodes = Maps.newHashMap();
        mStyleNodes = Maps.newHashMap();
    }

    @Override
    public Collection<String> getApplicableAttributes() {
        return Arrays.asList(
                ATTR_LAYOUT_WIDTH,
                ATTR_LAYOUT_HEIGHT,
                ATTR_STYLE
        );
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attr) {
        String name = attr.getLocalName();
        Element owner = attr.getOwnerElement();
        if (ATTR_LAYOUT_WIDTH.equals(name)) {
            mWidthNodes.put(owner, true);
        } else if (ATTR_LAYOUT_HEIGHT.equals(name)) {
            mHeightNodes.put(owner, true);
        } else if (ATTR_STYLE.equals(name)) {
            mStyleNodes.put(owner, attr);
        }
    }

    @Override
    public Collection<String> getApplicableElements() {
        return ALL;
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String tag = element.getTagName();
        if (tag.equals(MERGE_TAG) || tag.equals(INCLUDE_TAG) || tag.equals(TAG_FRAGMENT) ||
                tag.equals(TAG_REQUEST_FOCUS) || tag.equals(TAG_SCRIPT)) {
            return;
        }

        if (tag.equals(TAG_VIEW)) {
            String className = element.getAttribute(ATTR_CLASS);
            if (className != null && className.endsWith(GRID_LAYOUT)) {
                return;
            }
        } else if (tag.endsWith(GRID_LAYOUT)) {
            return;
        }

        // Record that we need to check this element later
        mWidthNodes.put(element, false);
        mHeightNodes.put(element, false);
    }

    @Override
    public void visitElementEnd(@NonNull XmlContext context, @NonNull Element element) {
        String tag = element.getTagName();
        if (tag.equals(MERGE_TAG) || tag.equals(INCLUDE_TAG) || tag.equals(TAG_FRAGMENT) ||
                tag.equals(TAG_REQUEST_FOCUS) || tag.equals(TAG_SCRIPT)) {
            return;
        }

        if (tag.equals(TAG_VIEW)) {
            String className = element.getAttribute(ATTR_CLASS);
            if (className != null && className.endsWith(GRID_LAYOUT)) {
                return;
            }
        } else if (tag.endsWith(GRID_LAYOUT)) {
            return;
        }

        Boolean hasWidth = mWidthNodes.get(element);
        Boolean hasHeight = mHeightNodes.get(element);
        if (hasWidth == null || hasHeight == null) {
            return;
        }

        if (!hasWidth || !hasHeight) {
            Attr styleAttr = mStyleNodes.get(element);
            if (styleAttr != null) {
                String style = styleAttr.getValue();
                if (style != null && !style.isEmpty() && hasSizeInStyle(context, style)) {
                    return;
                }
            }

            if (!hasWidth && !hasHeight) {
                context.report(ISSUE, element, context.getLocation(element),
                        "Missing both `layout_width` and `layout_height` attributes");
            } else if (!hasWidth) {
                context.report(ISSUE, element, context.getLocation(element),
                        "Missing `layout_width` attribute");
            } else {
                context.report(ISSUE, element, context.getLocation(element),
                        "Missing `layout_height` attribute");
            }
        }
    }

    private boolean hasSizeInStyle(@NonNull XmlContext context, @NonNull String style) {
        ResourceUrl url = ResourceUrl.parse(style);
        if (url == null || url.type != ResourceType.STYLE) {
            return false;
        }

        Project project = context.getMainProject();
        AbstractResourceRepository resources = project.getResourceRepository();
        if (resources == null) {
            return false;
        }

        String name = url.name;
        while (name != null) {
            List<ResourceItem> items = resources.getResourceItem(ResourceType.STYLE, name);
            if (items == null || items.isEmpty()) {
                return false;
            }
            ResourceValue value = items.get(0).getValue();
            if (!(value instanceof StyleResourceValue)) {
                return false;
            }
            StyleResourceValue styleValue = (StyleResourceValue) value;
            if (styleValue.getItem(ATTR_LAYOUT_WIDTH) != null
                    || styleValue.getItem(ATTR_LAYOUT_HEIGHT) != null) {
                return true;
            }
            String parent = styleValue.getParentStyle();
            if (parent == null) {
                return false;
            }
            url = ResourceUrl.parse(parent);
            if (url == null || url.type != ResourceType.STYLE) {
                return false;
            }
            name = url.name;
        }

        return false;
    }
}
